prompt --application/shared_components/navigation/lists/custom_navigation_menu
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(35079282461185659)
,p_name=>'Custom Navigation Menu'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT LEVEL,',
'       A.*',
'FROM ( SELECT',
'       DECODE(:P_LANG,''en'',A.ENTRY_TEXT,a.AR_ENTRY_TEXT )label,',
'       CASE',
'        WHEN A.PAGE_ID IS NOT NULL THEN',
'           ''f?p=&APP_ID.:'' || A.PAGE_ID || '':'' || :APP_SESSION || ''::NO:''|| DECODE(NVL(CLEAR_CACHE_FLAG,''N''), ''Y'' , A.PAGE_ID, NULL)',
'       ELSE',
'       NULL',
'       END AS VALUE,',
'       CASE',
'       WHEN :APP_PAGE_ID IN (SELECT  COLUMN_VALUE AS VAL FROM TABLE(APEX_STRING.SPLIT(CURRENT_LIST_ENTRY,'',''))) OR A.PAGE_ID = :APP_PAGE_ID THEN',
'       ''YES''',
'       ELSE',
'       ''NO''',
'       END AS is_current,',
'       ''fa fa '' || ENTRY_IMAGE AS IMAGE,',
'       A.LIST_ENTRY_PARENT_ID ,',
'       A.LIST_ENTRY_ID ,',
'       A.DISPLAY_SEQUENCE',
'  from APP_APPLICATION_PRIVILEGES A',
' WHERE A.APPLICATION_ID = :APP_ID',
'   AND A.LIST_ID = :P_LIST_ID',
'   AND SHOW_IN_MENU_FLAG = ''Y''',
'   AND APP_USER_SECURITY.user_menu_privilege (p_user_id => :P_USER_ID,p_object_type => :P_USER_TYPE , p_object_value => :P_USER_OBJECT_ID, p_page_id => A.PAGE_ID) = 1',
'   AND (A.ID IN',
'       (SELECT R.PRIVILEGE_ID',
'          FROM APP_ROLE_PRIVILEGES R',
'         WHERE ROLE_ID IN',
'               (SELECT V.ROLE_ID',
'                  FROM APP_USER_ROLES V',
'                 WHERE V.USER_ID IN',
'                       (SELECT U.ID',
'                          FROM APP_USERS U',
'                         WHERE UPPER(USER_NAME) = :APP_USER))))) A',
' start with A.LIST_ENTRY_PARENT_ID IS NULL',
'connect by prior A.LIST_ENTRY_ID = A.LIST_ENTRY_PARENT_ID',
' order siblings by A.DISPLAY_SEQUENCE'))
,p_list_status=>'PUBLIC'
,p_version_scn=>41802065918835
);
