'DECLARE',
'    v_query VARCHAR2(4000);',
'BEGIN',
'    IF :P17_OBJECT_TYPE = ''requester'' THEN',
'        v_query := ''SELECT DECODE(:P_LANG, ''''ar'''', NAME_AR, NAME_EN) AS D, ID AS R FROM INFATH_EXECUTION_REQUESTER'';',
'    ELSIF :P17_OBJECT_TYPE = ''against'' THEN',
'        v_query := ''SELECT DECODE(:P_LANG, ''''ar'''', NAME_AR, NAME_EN) AS D, ID AS R FROM INFATH_EXECUTED_AGAINST'';',
'    ELSIF :P17_OBJECT_TYPE = ''deputy'' THEN',
'        v_query := ''SELECT DECODE(:P_LANG, ''''ar'''', NAME_AR, NAME_EN) AS D, ID AS R FROM INFATH_DEPUTY_EXECUTION_REQUESTER'';',
'    ELSE',
'        v_query := ''SELECT NULL AS D, NULL AS R FROM DUAL'';',
'    END IF;',
'',
'    RETURN v_query;',
'END;'))
,p_source_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_location=>'LOCAL'
,p_return_column_name=>'R'
,p_display_column_name=>'D'
