'  "markerModifier": "fam-plus fam-is-info",',
'  "openParentOfActiveNode": true,',
'  "openParentOfSelected": true,',
'  "refresh": 0,',
'  "search": {',
'    "autoExpand": true,',
'    "leavesOnly": false,',
'    "highlight": true,',
'    "counter": true,',
'    "hideUnmatched": true,',
'    "debounce": {',
'      "enabled": true,',
'      "time": 400',
'    }',
