,p_process_name=>'INSERT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    INSERT INTO INFATH_DECISION (REQUEST_NUMBER, REPORT_NUMBER, FILE_ID, IS_ACTIVE)',
'        VALUES (:P3_REQUEST_NUMBER, :P3_REPORT_NUMBER, :P3_FILE_ID, 1)',
'    RETURNING ID INTO :P3_ID;',
'',
'    INSERT INTO INFATH_PROSECUTION_TYPE (NAME_AR, NAME_EN, PROSECUTION_NUMBER, PROSECUTION_SOURCE, PROSECUTION_DATE, INFATH_REPORT_ID)',
'        VALUES (:P3_PT_NAME_AR, :P3_PT_NAME_EN, :P3_PROSECUTION_NUMBER, :P3_PROSECUTION_SOURCE, :P3_PROSECUTION_DATE, :P3_ID)',
'    RETURNING ID INTO :P3_PT_ID;',
'',
'    INSERT INTO INFATH_EXECUTIVE_BOND (BOND_RATING, BOND_NUMBER, BOND_TYPE, BOND_SOURCE, EXECUTION_SEAL_NUMBER, BOND_DATE, AMOUNT_CLAIMED, INFATH_REPORT_ID)',
'        VALUES (:P3_BOND_RATING, :P3_BOND_NUMBER, :P3_BOND_TYPE, :P3_BOND_SOURCE, :P3_EXECUTION_SEAL_NUMBER, :P3_BOND_DATE, :P3_AMOUNT_CLAIMED, :P3_ID)',
'    RETURNING ID INTO :P3_EB_ID;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>16043399967587132
);
