,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UPDATE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE INFATH_DECISION',
'       SET REQUEST_NUMBER = :P3_REQUEST_NUMBER,',
'           REPORT_NUMBER  = :P3_REPORT_NUMBER',
'     WHERE ID = :P3_ID;',
'',
'    UPDATE INFATH_PROSECUTION_TYPE',
'       SET NAME_AR            = :P3_PT_NAME_AR,',
'           NAME_EN            = :P3_PT_NAME_EN,',
'           PROSECUTION_NUMBER = :P3_PROSECUTION_NUMBER,',
'           PROSECUTION_SOURCE = :P3_PROSECUTION_SOURCE,',
'           PROSECUTION_DATE   = :P3_PROSECUTION_DATE',
'     WHERE INFATH_REPORT_ID = :P3_ID;',
'',
'    UPDATE INFATH_EXECUTIVE_BOND',
'       SET BOND_RATING           = :P3_BOND_RATING,',
'           BOND_NUMBER           = :P3_BOND_NUMBER,',
'           BOND_TYPE             = :P3_BOND_TYPE,',
'           BOND_SOURCE           = :P3_BOND_SOURCE,',
'           EXECUTION_SEAL_NUMBER = :P3_EXECUTION_SEAL_NUMBER,',
'           BOND_DATE             = :P3_BOND_DATE,',
'           AMOUNT_CLAIMED        = :P3_AMOUNT_CLAIMED',
'     WHERE INFATH_REPORT_ID = :P3_ID;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>16043799620587133
);
