,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT IR.ID,',
'       IR.REPORT_NUMBER,',
'       IR.REQUEST_NUMBER,',
'       IR.CREATED_DATE,',
'       TO_CHAR(IR.CREATED_DATE ,''DD MONTH YYYY'', ''NLS_CALENDAR=''''Arabic Hijrah'''''') AS HIJRI_CREATED_DATE,',
'       EB.AMOUNT_CLAIMED,',
'       IU.ID AS UPLOAD_ID,',
'       IU.FILE_NAME,',
'       IU.MISSION_NUMBER,',
'       IU.REPORT_URL,',
'       IU.NOTES,',
'       NULL AS LINK',
'  FROM INFATH_DECISION IR, INFATH_EXECUTIVE_BOND EB, INFATH_UPLOAD_REPORT IU',
' WHERE IR.ID = EB.INFATH_REPORT_ID (+)',
'   AND IR.FILE_ID = IU.ID',
'   AND NVL(IR.IS_ACTIVE, 0) = 1',
'   AND NVL(IU.IS_ACTIVE, 0) = 1',
'   AND NVL(IU.IS_DISPLAYED, -1) = 0',
' ORDER BY IR.ID DESC;'))
