,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT IR.ID,',
'       IR.REPORT_NUMBER,',
'       IR.REQUEST_NUMBER,',
'       IR.CREATED_BY,',
'       IR.CREATED_DATE,',
'       TO_CHAR(IR.CREATED_DATE ,''DD MONTH YYYY'', ''NLS_CALENDAR=''''Arabic Hijrah'''''') AS HIJRI_CREATED_DATE,',
'       IR.MODIFIED_BY,',
'       IR.MODIFIED_DATE,    ',
'       TO_CHAR(IR.MODIFIED_DATE ,''DD MONTH YYYY'', ''NLS_CALENDAR=''''Arabic Hijrah'''''') AS HIJRI_MODIFIED_DATE,',
'       EB.AMOUNT_CLAIMED,',
'       NULL AS SET_VEHICLES,',
'       NULL AS CONTACT_RECORD,',
'       NULL AS REQUESTERS',
'  FROM INFATH_DECISION IR, INFATH_EXECUTIVE_BOND EB',
' WHERE IR.ID = EB.INFATH_REPORT_ID (+)',
'   AND NVL(IS_ACTIVE, 0) = 1',
