wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(27433817401204798)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    INSERT INTO INFATH_DECISION (REQUEST_NUMBER, REPORT_NUMBER, FILE_ID, IS_ACTIVE)',
'        VALUES (:P13_REQUEST_NUMBER, :P13_REPORT_NUMBER, :P13_FILE_ID, 1)',
'    RETURNING ID INTO :P13_ID;',
'',
'    INSERT INTO INFATH_PROSECUTION_TYPE (NAME_AR, NAME_EN, PROSECUTION_NUMBER, PROSECUTION_SOURCE, PROSECUTION_DATE, INFATH_REPORT_ID)',
'        VALUES (:P13_PT_NAME_AR, :P13_PT_NAME_EN, :P13_PROSECUTION_NUMBER, :P13_PROSECUTION_SOURCE, :P13_PROSECUTION_DATE, :P13_ID)',
'    RETURNING ID INTO :P13_PT_ID;',
'',
'    INSERT INTO INFATH_EXECUTIVE_BOND (BOND_RATING, BOND_NUMBER, BOND_TYPE, BOND_SOURCE, EXECUTION_SEAL_NUMBER, BOND_DATE, AMOUNT_CLAIMED, INFATH_REPORT_ID)',
'        VALUES (:P13_BOND_RATING, :P13_BOND_NUMBER, :P13_BOND_TYPE, :P13_BOND_SOURCE, :P13_EXECUTION_SEAL_NUMBER, :P13_BOND_DATE, :P13_AMOUNT_CLAIMED, :P13_ID)',
'    RETURNING ID INTO :P13_EB_ID;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(27433458032204794)
,p_internal_uid=>11370028450188742
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(27433965786204799)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UPDATE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE INFATH_DECISION',
'       SET REQUEST_NUMBER = :P13_REQUEST_NUMBER,',
'           REPORT_NUMBER  = :P13_REPORT_NUMBER',
'     WHERE ID = :P13_ID;',
'',
'    UPDATE INFATH_PROSECUTION_TYPE',
'       SET NAME_AR            = :P13_PT_NAME_AR,',
'           NAME_EN            = :P13_PT_NAME_EN,',
'           PROSECUTION_NUMBER = :P13_PROSECUTION_NUMBER,',
'           PROSECUTION_SOURCE = :P13_PROSECUTION_SOURCE,',
'           PROSECUTION_DATE   = :P13_PROSECUTION_DATE',
'     WHERE INFATH_REPORT_ID = :P13_ID;',
'',
'    UPDATE INFATH_EXECUTIVE_BOND',
'       SET BOND_RATING           = :P13_BOND_RATING,',
'           BOND_NUMBER           = :P13_BOND_NUMBER,',
'           BOND_TYPE             = :P13_BOND_TYPE,',
'           BOND_SOURCE           = :P13_BOND_SOURCE,',
'           EXECUTION_SEAL_NUMBER = :P13_EXECUTION_SEAL_NUMBER,',
'           BOND_DATE             = :P13_BOND_DATE,',
'           AMOUNT_CLAIMED        = :P13_AMOUNT_CLAIMED',
'     WHERE INFATH_REPORT_ID = :P13_ID;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(27433551247204795)
,p_internal_uid=>11370176835188743
);
