wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(27433283586204792)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET DATA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P13_ID IS NOT NULL THEN',
'        SELECT REQUEST_NUMBER, REPORT_NUMBER, CREATED_BY, CREATED_DATE, MODIFIED_BY, MODIFIED_DATE, FILE_ID',
'          INTO :P13_REQUEST_NUMBER, :P13_REPORT_NUMBER, :P13_CREATED_BY, :P13_CREATED_DATE, :P13_MODIFIED_BY, :P13_MODIFIED_DATE, :P13_FILE_ID',
'          FROM INFATH_DECISION',
'         WHERE ID = :P13_ID;',
'',
'        SELECT REPORT_URL',
'          INTO :P13_DECISION_FILE',
'          FROM INFATH_UPLOAD_REPORT',
'         WHERE ID = :P13_FILE_ID;',
'',
'        SELECT NAME_AR, NAME_EN, PROSECUTION_NUMBER, PROSECUTION_SOURCE, PROSECUTION_DATE',
'          INTO :P13_PT_NAME_AR, :P13_PT_NAME_EN, :P13_PROSECUTION_NUMBER, :P13_PROSECUTION_SOURCE, :P13_PROSECUTION_DATE',
'          FROM INFATH_PROSECUTION_TYPE',
'         WHERE INFATH_REPORT_ID = :P13_ID;',
'',
'        SELECT BOND_RATING, BOND_NUMBER, BOND_TYPE, BOND_SOURCE, EXECUTION_SEAL_NUMBER, BOND_DATE, AMOUNT_CLAIMED',
'          INTO :P13_BOND_RATING, :P13_BOND_NUMBER, :P13_BOND_TYPE, :P13_BOND_SOURCE, :P13_EXECUTION_SEAL_NUMBER, :P13_BOND_DATE, :P13_AMOUNT_CLAIMED',
'          FROM INFATH_EXECUTIVE_BOND',
'         WHERE INFATH_REPORT_ID = :P13_ID;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11369494635188736
);
end;
