 p_id=>wwv_flow_imp.id(32025686680792505)
,p_event_id=>wwv_flow_imp.id(32025567650792504)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'let ig$  = apex.region("region").widget(),',
'    view = ig$.interactiveGrid("getCurrentView");',
'',
'let gridView = apex.region("region").call("getViews").grid;',
'',
'//  Show/Hide COLUMNS',
'if ($v("P17_VEHICLES_STATUS_ID") === "coercive_force") {',
'    gridView.view$.grid("showColumn", "REFUSER_NAME");',
'    gridView.view$.grid("showColumn", "REFUSER_IDENTITY_NO");',
'    gridView.view$.grid("showColumn", "REFUSER_PHONE");',
'} else if ($v("P17_VEHICLES_STATUS_ID") === "reservation_government_private") {',
'    gridView.view$.grid("hideColumn", "REFUSER_NAME");',
'    gridView.view$.grid("hideColumn", "REFUSER_IDENTITY_NO");',
'    gridView.view$.grid("hideColumn", "REFUSER_PHONE");',
'    gridView.view$.grid("showColumn", "ENTITY_TYPE");',
'    gridView.view$.grid("showColumn", "ENTITY_NAME");',
'} else if ($v("P17_VEHICLES_STATUS_ID") === "unable_withdraw") {',
'    gridView.view$.grid("hideColumn", "REFUSER_NAME");',
'    gridView.view$.grid("hideColumn", "REFUSER_IDENTITY_NO");',
'    gridView.view$.grid("hideColumn", "REFUSER_PHONE");',
'    gridView.view$.grid("hideColumn", "ENTITY_TYPE");',
'    gridView.view$.grid("hideColumn", "ENTITY_NAME");',
'    gridView.view$.grid("showColumn", "UNABLE_WITHDRAW_REASON");',
'    gridView.view$.grid("showColumn", "ATTACHED_URL");',
'} else {',
'    gridView.view$.grid("hideColumn", "REFUSER_NAME");',
'    gridView.view$.grid("hideColumn", "REFUSER_IDENTITY_NO");',
'    gridView.view$.grid("hideColumn", "REFUSER_PHONE");',
