wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(28051050508345883)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Files'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_error_msg         VARCHAR2(500);',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P997_FILES,',
'                        p_sep => '':'' );',
'',
'    IF l_file_names.count = 0 THEN',
'        IF :P_LANG = ''ar'' THEN',
unistr('            l_error_msg := ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \0627\0644\0645\0644\0641 \0623\0648\0644\0627'';'),
'        ELSE',
'            l_error_msg := ''You Should upload your file first!'';',
'        END IF;',
'        RAISE_APPLICATION_ERROR(-20001, l_error_msg);',
'    END IF;',
'',
'    IF l_file_names.count > 1 AND :P997_IS_MULTIFILES = ''N'' THEN',
'        IF :P_LANG = ''ar'' THEN',
unistr('            l_error_msg := ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \0645\0644\0641 \0648\0627\062D\062F \0641\0642\0637'';'),
'        ELSE',
'            l_error_msg := ''You Should upload only one file'';',
'        END IF;',
'        RAISE_APPLICATION_ERROR(-20001, l_error_msg);',
'    END IF;',
'',
'    IF l_file_names.count > 1 THEN',
'        FOR i IN 1 .. l_file_names.count LOOP',
'            SELECT *',
'              INTO l_file',
'              FROM APEX_APPLICATION_TEMP_FILES',
'             WHERE NAME = l_file_names(i);',
'',
'            l_request_url := :G_OCI_BASE_URL||''/b/''||:P997_BUCKET_NAME||''/o/''',
'                             || regexp_replace(APEX_UTIL.url_encode(l_file.FILENAME), ''[^0-9]'', '''')',
'                            --  || ''-''|| DBMS_RANDOM.STRING(''a'', 6)',
'                             || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'            ',
'            l_result := APEX_WEB_SERVICE.make_rest_request (',
'                            p_url                  => l_request_url,',
'                            p_http_method          => ''PUT'',',
'                            p_body_blob            => l_file.BLOB_CONTENT,',
'                            p_credential_static_id => ''OCI_AUTH''',
'                        );',
'',
'            IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'                SYSTEM_CONTROLS.ERROR_LOGS(p_ERROR_TYPE => ''SYSTEM_ERROR'',p_PROCESS_NAME => ''OCI_OS.put_object'',p_ERROR_CODE => -2,p_ERROR_MESSAGE => SUBSTR(l_result, 1, 4000), p_logger_name => :APP_USER);',
'                IF :P_LANG = ''ar'' THEN',
unistr('                    l_error_msg := ''\062E\0637\0623 \0641\064A \062A\062D\0645\064A\0644 \0627\0644\0628\064A\0627\0646\0627\062A'';'),
'                ELSE',
'                    l_error_msg := ''Error with uploading Data!'';',
'                END IF;',
'                RAISE_APPLICATION_ERROR(-20001, l_error_msg);',
'            END IF;',
'',
'            INSERT INTO INFATH_UPLOAD_REPORT(FILE_NAME, REPORT_URL, /*STATUS,*/ IS_ACTIVE, IS_DISPLAYED)',
'                VALUES (REGEXP_REPLACE(APEX_UTIL.url_encode(l_file.FILENAME), ''[^0-9]'', ''''), l_request_url,',
'                        /*LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''work_done'', p_lookup_code => ''decision_status''),*/ 1, 1);',
'        END LOOP;',
'',
'    ELSE    ',
'        SELECT *',
'          INTO l_file',
'          FROM APEX_APPLICATION_TEMP_FILES',
'         WHERE NAME = :P997_FILES;',
'',
'        l_request_url := :G_OCI_BASE_URL||''/b/''||:P997_BUCKET_NAME||''/o/''',
'                         || REGEXP_REPLACE(APEX_UTIL.url_encode(l_file.FILENAME), ''[^0-9]'', '''')',
'                        --  || ''-''|| DBMS_RANDOM.STRING(''a'', 6)',
'                         || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'        ',
'        l_result := APEX_WEB_SERVICE.make_rest_request (',
'                        p_url                  => l_request_url,',
'                        p_http_method          => ''PUT'',',
'                        p_body_blob            => l_file.BLOB_CONTENT,',
'                        p_credential_static_id => ''OCI_AUTH''',
'                    );',
'',
'        IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'            SYSTEM_CONTROLS.ERROR_LOGS(p_ERROR_TYPE => ''SYSTEM_ERROR'',p_PROCESS_NAME => ''OCI_OS.put_object'',p_ERROR_CODE => -2,p_ERROR_MESSAGE => SUBSTR(l_result, 1, 4000), p_logger_name => :APP_USER);',
'            IF :P_LANG = ''ar'' THEN',
unistr('                l_error_msg := ''\062E\0637\0623 \0641\064A \062A\062D\0645\064A\0644 \0627\0644\0628\064A\0627\0646\0627\062A'';'),
'            ELSE',
'                l_error_msg := ''Error with uploading Data!'';',
'            END IF;',
'            RAISE_APPLICATION_ERROR(-20001, l_error_msg || APEX_WEB_SERVICE.g_status_code || '' - '' || l_request_url);',
'        END IF;',
'    ',
'        :P997_RETURNED_URL := l_request_url;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>11987261557329827
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(28051411231345884)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_CLOSE_WINDOW'
,p_process_name=>'Close Dialog'
