,p_item_plug_id=>wwv_flow_imp.id(99353421499483123)
,p_prompt=>'Doc Type'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT NAME AS D,',
'       TYPE AS R',
'  FROM (',
unistr('      SELECT ''\0635\0643 \0627\0644\0645\0644\0643\064A\0629'' AS NAME , ''prop_ownership'' AS TYPE , LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''notary_attach'', p_lookup_code => ''app_objects'')  AS OBJECT_YPE FROM DUAL'),
'      UNION ALL',
unistr('      SELECT ''\0637\0644\0628 \062A\0633\062C\064A\0644 \0644\0644\063A\064A\0631'' AS NAME , ''prop_other_register'' AS TYPE , LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''notary_attach'', p_lookup_code => ''app_objects'')  AS OBJECT_YPE FROM DUAL WHERE :P10_OBJECT_FLAG = 0'),
'      UNION ALL',
unistr('      SELECT ''\0627\0644\0641\0627\062A\0648\0631\0629 \0627\0644\0636\0631\064A\0628\064A\0629'' AS NAME , ''acc_tax_invoice'' AS TYPE , LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''supervisor-attachments'', p_lookup_code => ''app_objects'')  AS OBJECT_YPE FROM DUAL'),
'      UNION ALL',
unistr('      SELECT ''\0627\064A\0635\0627\0644 \0627\0644\062F\0641\0639'' AS NAME , ''payment_reference'' AS TYPE , LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''accountant_attach'', p_lookup_code => ''app_objects'')  AS OBJECT_YPE '),
'        FROM DUAL',
'       WHERE EXISTS (SELECT 1 FROM CLIENT_PROPERTIES WHERE CLIENT_PROPERTY_ID = :P10_OBJECT_ID AND NVL(STATUS,0) IN (1,2,3)) ',
'      UNION ALL',
unistr('      SELECT ''\062A\0642\0631\064A\0631 \0627\0644\0627\0646\062C\0627\0632 \0644\0648\0627\0641\064A'' AS NAME , ''drawing_wafi_reports'' AS TYPE , LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''drawing_reports'', p_lookup_code => ''app_objects'') AS OBJECT_YPE FROM DUAL '),
'      UNION ALL',
unistr('      SELECT ''\062A\0642\0631\064A\0631 \0627\0644\0645\062B\0645\0646'' AS NAME , ''drawing_pricing_report'' AS TYPE , LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''drawing_reports'', p_lookup_code => ''app_objects'') AS OBJECT_YPE FROM DUAL '),
'      UNION ALL',
unistr('      SELECT ''\0645\0631\062C\0639 \0627\0644\062A\062D\0648\064A\0644'' AS NAME , ''references'' AS TYPE, LOOKUPS_MNT.lookup_detail_id_by_code(p_lookup_detail_code => ''transfers_ref'', p_lookup_code => ''app_objects'')  AS OBJECT_YPE FROM DUAL '),
'  )  ',
'WHERE OBJECT_YPE = NVL(:P999_OBJECT_TYPE,0)',
'  AND (TYPE = :P999_DOC_TYPE',
'        OR :P999_DOC_TYPE IS NULL)'))
,p_lov_display_null=>'YES'
