wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(27251444490706526)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Files'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names    APEX_T_VARCHAR2;',
'    l_file          apex_application_temp_files%rowtype;',
'    l_file_name     VARCHAR2(255);',
'    l_result        NUMBER;',
'    v_is_lab        NUMBER := 1;',
'    v_bucket        VARCHAR2(20);',
'    v_url           VARCHAR2(1000); ',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P999_FILES,',
'                        p_sep => '':'' );',
'',
'    IF l_file_names.count = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''You Should upload your file!'');',
'    END IF;',
'',
'    IF l_file_names.count > 1 AND :P999_MULTIFILES_FLAG = ''N'' THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''You Should upload one file only.'');',
'    END IF;                    ',
'',
'    IF v_is_lab = 1 THEN',
'        v_bucket := ''mobasher-v1-upload'';',
'    ELSIF v_is_lab = 0 THEN',
'        v_bucket := ''mobasher-v1-upload'';',
'    END IF;',
'',
'    IF l_file_names.count > 1 THEN                    ',
'        FOR i IN 1 .. l_file_names.count LOOP',
'            SELECT *',
'              INTO l_file',
'              FROM apex_application_temp_files',
'             WHERE name = l_file_names(i);',
'',
'            l_file_name := TO_CHAR(get_current_date,''YY'') ',
'                            || LPAD(:P999_TABLE_ID, 6, ''0'') ',
'                            || :P999_TABLE_TYPE ',
'                            || DBMS_RANDOM.STRING(''x'', 6)',
'                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'            l_result := AWS4_S3_PKG.put_object (',
'                            p_bucket     => v_bucket,',
'                            p_blob       => l_file.BLOB_CONTENT,',
'                            p_object_key => ''/mobasher/''||:P999_FOLDER_NAME||''/''||l_file_Name,',
'                            p_mimetype   => l_file.MIME_TYPE',
'                    );',
'',
'            IF l_result <> 1 THEN',
'                RAISE_APPLICATION_ERROR(-20001 , ''Error with uploading Data!'');',
'            END IF;',
'',
'            v_url := ''https://''||v_bucket||''.s3.ap-south-1.amazonaws.com/mobasher/'' || :P999_FOLDER_NAME || ''/'' || l_file_Name;',
'',
'            IF :P999_IS_INSERT = 1 THEN',
'                INSERT INTO APP_DOCUMENTS(OBJECT_TYPE, OBJECT_ID, URL, IS_ACTIVE, FILE_NAME)',
'                    VALUES (NVL(:P999_OBJECT_TYPE, :P999_TABLE_TYPE), :P999_TABLE_ID, v_url, 1, l_file_names(i));',
'            END IF;',
'        END LOOP;',
'    ELSE',
'        SELECT *',
'          INTO l_file',
'          FROM apex_application_temp_files',
'         WHERE name = :P999_FILES;',
'',
'        l_file_name := NVL(:P999_FILE_URL,TO_CHAR(get_current_date,''YY'') ',
'                                            || LPAD(:P999_TABLE_ID, 6, ''0'') ',
'                                            || :P999_TABLE_TYPE ',
'                                            || DBMS_RANDOM.STRING(''x'', 6)',
'                                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE));',
'',
'        l_result := AWS4_S3_PKG.put_object (',
'                        p_bucket     => v_bucket,',
'                        p_blob       => l_file.BLOB_CONTENT,',
'                        p_object_key => ''/mobasher/''||:P999_FOLDER_NAME||''/''||l_file_Name,',
'                        p_mimetype   => l_file.MIME_TYPE',
'                );',
'',
'        IF l_result <> 1 THEN',
'            RAISE_APPLICATION_ERROR(-20001 , ''Error with uploading Data!'');',
'        END IF;',
'',
'        v_url := ''https://''||v_bucket||''.s3.ap-south-1.amazonaws.com/mobasher/'' || :P999_FOLDER_NAME || ''/'' || l_file_Name;',
'',
'        IF :P999_IS_INSERT = 1 THEN',
'            IF :P999_UNIQUE = 1 THEN',
'                UPDATE APP_DOCUMENTS',
'                   SET URL = v_url',
'                 WHERE OBJECT_ID = :P999_TABLE_ID',
'                   AND OBJECT_TYPE = NVL(:P999_OBJECT_TYPE, :P999_TABLE_TYPE)',
'                   AND IS_ACTIVE = 1;',
'',
'                IF SQL%ROWCOUNT = 0 THEN',
'                    INSERT INTO APP_DOCUMENTS(OBJECT_TYPE, OBJECT_ID, URL, IS_ACTIVE, FILE_NAME)',
'                        VALUES (NVL(:P999_OBJECT_TYPE,:P999_TABLE_TYPE), :P999_TABLE_ID, v_url, 1, :P999_FILES);',
'                END IF;',
'            ELSE',
'                INSERT INTO APP_DOCUMENTS(OBJECT_TYPE, OBJECT_ID, URL, IS_ACTIVE, FILE_NAME)',
'                    VALUES (NVL(:P999_OBJECT_TYPE,:P999_TABLE_TYPE), :P999_TABLE_ID, v_url, 1, :P999_FILES);',
'            END IF;',
'        END IF;',
'',
'        :P999_RETURNED_URL := v_url ;',
'    END IF;    ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>11187655539690470
);
