,p_plug_new_grid_row=>false
,p_plug_grid_column_span=>6
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM ( SELECT ',
'     a.APPLICATION_ID || A.LIST_ENTRY_ID AS ID,',
'     a.APPLICATION_ID || A.LIST_ENTRY_PARENT_ID AS PARENT_ID,',
'     DECODE(NVL(:P_LANG, ''en''), ''ar'', A.AR_ENTRY_TEXT, A.ENTRY_TEXT) AS TITLE,',
'     A.ID AS VALUE,',
'     CASE',
'         WHEN ROWNUM <= 8 THEN',
'            10',
'         ELSE',
'            20',
'     END AS TYPE,',
'     A.ID AS TOOLTIP,',
'     ''fa fa ''||ENTRY_IMAGE AS ICON,',
'     CASE',
'        WHEN (SELECT COUNT(1) FROM APP_ROLE_PRIVILEGES R WHERE ROLE_ID = :P2003_ROLE_ID AND A.ID = R.PRIVILEGE_ID) >= 1 THEN',
'            1',
'        ELSE',
'            0',
'     END AS SELECTED,',
'     0 AS EXPANDED,',
'     1 AS CHECKBOX,',
'     0 AS UNSELECTABLE,',
'     DISPLAY_SEQUENCE,',
'     A.LIST_ENTRY_PARENT_ID,',
'     A.LIST_ENTRY_ID',
'FROM APP_APPLICATION_PRIVILEGES A',
'WHERE  A.APPLICATION_ID = :APP_ID AND A.LIST_ID = :P_LIST_ID) A',
'--and a.LIST_ENTRY_ID <> ''16614064878790872''',
'START WITH A.LIST_ENTRY_PARENT_ID IS NULL',
'CONNECT BY PRIOR A.LIST_ENTRY_ID = A.LIST_ENTRY_PARENT_ID',
'ORDER SIBLINGS BY A.DISPLAY_SEQUENCE'))
,p_plug_source_type=>'PLUGIN_APEX.FANCYTREE.SELECT'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', wwv_flow_string.join(wwv_flow_t_varchar2(
    '{',
    '  "checkbox": "fa-square-o",',
    '  "checkboxSelected": "fa-check-square",',
    '  "checkboxUnknown": "fa-square",',
    '  "selectMode": 2,',
    '  "typeSettings": [',
    '      {',
    '          "id": 10,',
    '          "storeItem": "P2003_ITEM",',
