 p_id=>wwv_flow_imp.id(35295267581321673)
,p_validation_name=>'Check User name / password'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_password        VARCHAR2(4000);',
'   l_stored_password VARCHAR2(4000);',
'BEGIN',
'    SELECT PASSWORD',
'      INTO l_stored_password',
'      FROM APP_USERS',
'     WHERE UPPER(USER_NAME) = UPPER(:P2008_USER_NICKNAME);',
'      ',
'    l_password := APP_USER_SECURITY.get_hash(:P2008_USER_NICKNAME, :P2008_CURRENT_PASSWORD);',
'      ',
'    IF l_password = l_stored_password THEN',
'        RETURN TRUE;',
'    ELSE ',
'        RETURN FALSE;',
'    END IF;',
'      ',
'EXCEPTION ',
'    WHEN NO_DATA_FOUND THEN',
'      RETURN FALSE;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Wrong Username and/or Password!'
,p_associated_item=>wwv_flow_imp.id(35294792992321668)
,p_error_display_location=>'INLINE_WITH_FIELD'
);
