wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(35295109075321672)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Password'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_password VARCHAR2(500);',
'    v_username VARCHAR2(255);',
'BEGIN',
'    IF :P2008_IS_FROM_LOGIN_PAGE = 1 THEN',
'        SELECT COUNT(1)',
'          INTO v_username',
'          FROM APP_USERS',
'         WHERE UPPER(USER_NAME) = UPPER(:P2008_USER_NICKNAME);',
'        ',
'        IF v_username = 0 THEN',
'            RAISE_APPLICATION_ERROR( -20001, SYSTEM_CONTROLS.get_translation(p_code => ''username_doe_not_exist'', p_lang => NVL(:P_LANG, ''en'')) );',
'        END IF;',
'    END IF;',
'',
'    v_password := APP_USER_SECURITY.get_hash(:P2008_USER_NICKNAME, :P2008_PASSWORD);',
'   ',
'    UPDATE APP_USERS',
'       SET PASSWORD = v_password,',
'           CHANGE_PASS_NEXT_LOGIN = ''N''',
'     WHERE UPPER(USER_NAME) = UPPER(:P2008_USER_NICKNAME);',
'',
'    IF SQL%ROWCOUNT = 0 THEN ',
'        RAISE_APPLICATION_ERROR( -20001, SYSTEM_CONTROLS.get_translation(p_code => ''password_change_error'', p_lang => NVL(:P_LANG, ''en'')) );',
'    END IF;  ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(35295002279321671)
,p_process_success_message=>'Password Changed Successfully.'
,p_internal_uid=>19231320124305616
);
end;
